use crate::{RepoPath, SourceSet};

#[cfg(test)]
mod tests;

const VENDORED_FOLDERS: [&str; 2] = ["vendor", "third_party"];
const BUILD_OUTPUT_FOLDERS: [&str; 4] = ["dist", "build", "out", "coverage"];
const LONGEST_AVERAGE_LINE_OF_WRITTEN_CODE: usize = 250;

pub const STANDARD_GENERATED_MARKERS: [&str; 6] = [
    "@generated",
    "auto-generated",
    "autogenerated",
    "automatically generated",
    "do not edit",
    "generated by",
];

pub fn settle_source_set(path: &RepoPath, text: &str, named_by_plugin: SourceSet) -> SourceSet {
    if has_folder_named(path.as_str(), &VENDORED_FOLDERS) {
        SourceSet::Vendored
    } else if has_folder_named(path.as_str(), &BUILD_OUTPUT_FOLDERS)
        || has_longer_average_line_than_written_code(text)
    {
        SourceSet::Generated
    } else {
        named_by_plugin
    }
}

pub fn has_folder_named(path: &str, names: &[&str]) -> bool {
    let Some((folders, _file_name)) = path.rsplit_once('/') else {
        return false;
    };
    folders.split('/').any(|folder| names.contains(&folder))
}

pub fn path_file_name(path: &str) -> &str {
    path.rsplit('/').next().unwrap_or(path)
}

pub fn has_generated_header_marker(comment: &str) -> bool {
    has_any_ascii_marker(comment, &STANDARD_GENERATED_MARKERS)
}

pub fn has_generated_header_marker_with_extra(comment: &str, extra_markers: &[&str]) -> bool {
    has_generated_header_marker(comment) || has_any_ascii_marker(comment, extra_markers)
}

pub fn has_any_ascii_marker(text: &str, markers: &[&str]) -> bool {
    markers
        .iter()
        .any(|marker| contains_ascii_ignore_case(text, marker))
}

pub fn contains_ascii_ignore_case(haystack: &str, needle: &str) -> bool {
    let haystack = haystack.as_bytes();
    let needle = needle.as_bytes();
    if needle.is_empty() {
        return true;
    }
    haystack
        .windows(needle.len())
        .any(|window| window.eq_ignore_ascii_case(needle))
}

fn has_longer_average_line_than_written_code(text: &str) -> bool {
    let (lines, characters) = text
        .lines()
        .filter(|line| !line.trim().is_empty())
        .fold((0_usize, 0_usize), |(lines, characters), line| {
            (lines + 1, characters + line.chars().count())
        });
    characters > lines.saturating_mul(LONGEST_AVERAGE_LINE_OF_WRITTEN_CODE)
}
